package com.ecotrack.backend.admin;
import com.ecotrack.backend.emission.*; import com.ecotrack.backend.user.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController{private final UserRepository users;private final EmissionFactorRepository factors;public AdminController(UserRepository u,EmissionFactorRepository f){users=u;factors=f;}@GetMapping("/users") public List<User> users(){return users.findAll();}@GetMapping("/emission-factors") public List<EmissionFactor> factors(){return factors.findAll();}@PostMapping("/emission-factors") public EmissionFactor create(@RequestBody EmissionFactor f){return factors.save(f);}@PutMapping("/emission-factors/{id}") public EmissionFactor update(@PathVariable Long id,@RequestBody EmissionFactor in){EmissionFactor f=factors.findById(id).orElseThrow();f.setCategory(in.getCategory());f.setActivityType(in.getActivityType());f.setFactor(in.getFactor());f.setUnit(in.getUnit());f.setSource(in.getSource());f.setRegion(in.getRegion());f.setVersion(in.getVersion());f.setValidFrom(in.getValidFrom());f.setValidTo(in.getValidTo());f.setActive(in.isActive());return factors.save(f);}@DeleteMapping("/emission-factors/{id}") public void delete(@PathVariable Long id){factors.deleteById(id);}}
